const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Recupera as duas entradas consolidadas pelo nó Merge ou nós anteriores
// Se o Merge combinou os dados no item atual:
const inputData = $input.first().json;

// Garante o acesso à lista de clientes e à lista de investimentos
const clientes = inputData.clientes ?? $("Webhook").first().json.body.clientes ?? [];
const investimentos = inputData.investimentos ?? $("Code").first().json.investimentos ?? [];

// Função auxiliar para converter "R$ 12.500,00" em número real (12500.00)
function limparSaldo(saldoStr) {
  if (typeof saldoStr === "number") return saldoStr;
  const limpo = String(saldoStr || "")
    .replace(/[R$\s]/g, "")
    .replaceAll(".", "")
    .replace(",", ".");
  return parseFloat(limpo) || 0;
}

// 2. Itera sobre cada cliente e cruza com a tabela de investimentos
const resultado = clientes.map(cliente => {
  const saldoNumerico = limparSaldo(cliente.saldo);

  // Filtra os produtos correspondentes ao perfil do cliente cujo valor mínimo cabe no saldo
  const produtosRecomendados = investimentos.filter(inv => {
    const mesmoPerfil = String(inv.perfil).toLowerCase() === String(cliente.perfil).toLowerCase();
    const cabeNoOrcamento = saldoNumerico >= Number(inv.minimo);
    return mesmoPerfil && cabeNoOrcamento;
  });

  // Monta a lista formatada de recomendações para o texto
  let listaProdutosTexto = "";
  if (produtosRecomendados.length > 0) {
    listaProdutosTexto = produtosRecomendados.map(p => 
      `• ${p.produto} (Mínimo: R$ ${p.minimo} | Rentabilidade: ${p.rentabilidade})`
    ).join("\n");
  } else {
    listaProdutosTexto = "• No momento, recomendamos manter em reserva de emergência diária.";
  }

  // 3. Constrói o texto final da mensagem
  const mensagem = `Olá, ${cliente.nome}!\n\n` +
    `Identificamos que seu perfil de investidor é *${cliente.perfil}* e seu saldo disponível é de *${cliente.saldo}*.\n\n` +
    `Com base nisso, selecionamos as melhores oportunidades para sua carteira:\n` +
    `${listaProdutosTexto}\n\n` +
    `Bons investimentos!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldoNumerico: saldoNumerico,
      perfil: cliente.perfil,
      produtosRecomendados: produtosRecomendados,
      mensagem: mensagem
    }
  };
});

return resultado;
